import "./css/Festval_CardList.css";
import Festval_CardItem from "./Festval_CardItem.js";

import axios from "axios";
import { useEffect, useState } from "react";

const Festval_CardList = (props) =>{

    const [cardItems, setCardItems] = useState(null);
    
    useEffect(() => {
        const Loging = async() => { // async를 사용하는 함수 따로 선언

          const today = props.today;

            const baseUrl = "http://apis.data.go.kr/B551011/KorService1/searchFestival1";
            //const serviceKey = "";
            const serviceKey = "Av0j4qFKXlogzFTNST8uPV8AmR6bdc5h9gNecQv1RR7v92yhfpCYFHj19OoN6mlq00fxLxYyEif4u5cu2GP%2BQA%3D%3D";
            const MobileOS = "ETC";
            const MobileApp = "Nado";            
            const eventStartDate = today.year() + "" + today.month() + "" + today.day();
            const type = "json";
            
            try{
              const response = await axios.get(baseUrl+"?serviceKey="+serviceKey+"&MobileOS="+MobileOS+"&MobileApp="+MobileApp+"&arrange=A&listYN=Y&eventStartDate="+eventStartDate+"&_type="+type);        
              console.log("여기야~~~~~~~");
              console.log(window.navigator.userAgent);
              console.log(window);
              setCardItems(response.data.response.body.items.item);                  
            }catch(e){      
              console.log(e);
            }
          };
          Loging();
    },[]);

    if(!cardItems){ // 축제리스트의 값이 null일때
      return null;
    }

    // 값이 있을때
    if(cardItems != null)      
    return (      
        <div className='card_list'>
            {cardItems.map(cardItem => (
                <Festval_CardItem key={cardItem.title} cardItem = {cardItem} today = {props.today}/>//컨포넌트에서 today한번만 구하면 되게끔 설정.
            )
          )}                    
        </div>
    );
}

export default Festval_CardList;
